    paragraphs = doc.paragraphs
    insert_count = 0
    
    for i in range(len(paragraphs) - 1, -1, -1):
        p = paragraphs[i]
        text = p.text.strip()
        
        for key, paras_to_insert in list(expansion_dict.items()):
            # We use 'in' to handle varied heading numbers or spaces
            if key in text and len(text) < 150: 
                for new_text in reversed(paras_to_insert):
                    new_p = doc.add_paragraph(new_text)
                    new_p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
                    for run in new_p.runs:
                        run.font.name = 'Times New Roman'
                        run.font.size = Pt(12)
                    
                    p._element.addnext(new_p._element)
                    insert_count += 1
                
                del expansion_dict[key]
                break

    print(f"Successfully injected {insert_count} massive paragraphs (Phase 3).")
    
